import fs from "node:fs";
import path from "node:path";
import data from "./templates.json";
import { SITE_URL } from "./site";

// Generated by scripts/site/templates.mjs from templates/ and templates-pro.json. A Pro template has
// metadata and a public preview here; its files live in a private repo (lib/templates-pro-api.ts).

export type TemplateInput = { key: string; label: string; default: string; where: string };
export type TemplateSlot = { key: string; label: string; kind: "image" | "video"; size: string; file: string; where: string; span?: number };
export type Template = {
  id: string;
  title: string;
  summary: string;
  category: string;
  tier: "free" | "pro";
  length: number;
  aspect: string;
  structure: string;
  inputs: TemplateInput[];
  slots: TemplateSlot[];
  tags: string[];
  hash: string;
  hasSource: boolean;
};
export type TemplateCard = Pick<Template, "id" | "title" | "summary" | "category" | "tier" | "length" | "hash">;
export type Category = { id: string; label: string };

export const CATEGORIES = data.categories as Category[];
export const TEMPLATES = data.templates as Template[];

export const templatesTitle = (n = TEMPLATES.length) => (n ? `${n} video templates you remix with one command | vawe` : "Video templates | vawe");
export const TEMPLATES_DESCRIPTION =
  "Finished films you copy and change. Each template is one HTML page that vawe renders to video. Start one with a single command.";
export const TEMPLATES_INTRO =
  "A template is a finished film. Copy it, change the words, and render it. Free templates are open source. Pro templates unlock with a license key.";

export const templateById = (id: string, list: Template[] = TEMPLATES) => list.find((t) => t.id === id) ?? null;
export const categoryLabel = (id: string) => CATEGORIES.find((c) => c.id === id)?.label ?? id;
export const toCard = ({ id, title, summary, category, tier, length, hash }: Template): TemplateCard => ({ id, title, summary, category, tier, length, hash });

export { templateFiles } from "./template-urls";

export const newCommand = (id: string) => `npx vawe new my-film --template ${id}`;

export const slotCommand = (id: string, slots: TemplateSlot[]) =>
  `${newCommand(id)}${slots.slice(0, 2).map((s) => ` --slot ${s.key}=~/path/to/${s.kind === "video" ? "clip.mp4" : "picture.png"}`).join("")}`;

export const checkoutUrl = () => process.env.NEXT_PUBLIC_POLAR_CHECKOUT_PRO || "/templates#pro";

export const templateSource = (id: string) => fs.readFileSync(path.join(process.cwd(), "public", "templates", `${id}.page.html`), "utf8");

export const publicMetadata = (list: Template[] = TEMPLATES) =>
  list.map(({ hash: _hash, hasSource: _hasSource, ...t }) => ({
    ...t,
    url: `${SITE_URL}/templates/${t.id}`,
    preview: `${SITE_URL}/templates/${t.id}.mp4`,
    poster: `${SITE_URL}/templates/${t.id}.webp`,
  }));
